using System;
using System.Linq;
using System.Collections.Generic;
using Server;
using Server.Items;
using Server.Mobiles;
using Server.Commands;
using Server.Targeting;
namespace Server.HavenPrototype {
 public class HavenEquipmentEvolution:Item {
  static readonly Dictionary<int,HavenEquipmentEvolution> Records=new Dictionary<int,HavenEquipmentEvolution>();
  public Item Equipment;public int Experience;public int Kind; // 0 boarding shield, 1 companion weapon, 2 companion grimoire, 3 companion shield, 4 Haven jewelry
  public int Level{get{return Math.Min(20,1+Experience/100);}}
  public HavenEquipmentEvolution(Item item,int kind):base(1){Equipment=item;Kind=kind;Visible=false;Movable=false;Internalize();Records[item.Serial.Value]=this;Apply();}
  public HavenEquipmentEvolution(Serial s):base(s){}
  public static HavenEquipmentEvolution Attach(Item item,int kind){if(item==null||item.Deleted)return null;HavenEquipmentEvolution record;if(Records.TryGetValue(item.Serial.Value,out record)&&!record.Deleted)return record;return new HavenEquipmentEvolution(item,kind);}
  public static HavenEquipmentEvolution Find(Item item){HavenEquipmentEvolution record;return item!=null&&Records.TryGetValue(item.Serial.Value,out record)&&!record.Deleted?record:null;}
  public void Gain(int amount){if(amount<=0||Equipment==null||Equipment.Deleted)return;Experience=Math.Min(1900,Experience+amount);Apply();}
  public void Apply(){if(Equipment==null||Equipment.Deleted)return;int step=Level-1;var weapon=Equipment as BaseWeapon;var shield=Equipment as BaseShield;var book=Equipment as Spellbook;if(weapon!=null){weapon.Attributes.WeaponDamage=Math.Max(weapon.Attributes.WeaponDamage,30+step*30/19);weapon.Attributes.AttackChance=Math.Max(weapon.Attributes.AttackChance,10+step*5/19);weapon.Attributes.WeaponSpeed=Math.Max(weapon.Attributes.WeaponSpeed,step*20/19);weapon.WeaponAttributes.HitLeechMana=Math.Max(weapon.WeaponAttributes.HitLeechMana,60+step*40/19);weapon.WeaponAttributes.HitLeechHits=Math.Max(weapon.WeaponAttributes.HitLeechHits,30+step*30/19);Equipment.Name="Companion's "+(weapon is BaseRanged?"bow":"blade");}else if(shield!=null){shield.Attributes.DefendChance=Math.Max(shield.Attributes.DefendChance,15);shield.Attributes.AttackChance=Math.Max(shield.Attributes.AttackChance,10+step*5/19);shield.Attributes.BonusHits=Math.Max(shield.Attributes.BonusHits,15+step*15/19);shield.Attributes.BonusStam=Math.Max(shield.Attributes.BonusStam,10+step*10/19);shield.Attributes.RegenHits=Math.Max(shield.Attributes.RegenHits,3+step*2/19);shield.Attributes.RegenMana=Math.Max(shield.Attributes.RegenMana,3+step*2/19);shield.Attributes.RegenStam=Math.Max(shield.Attributes.RegenStam,3+step*2/19);shield.Attributes.LowerManaCost=Math.Max(shield.Attributes.LowerManaCost,5+step*5/19);shield.PhysicalBonus=Math.Max(shield.PhysicalBonus,10+step*5/19);shield.FireBonus=Math.Max(shield.FireBonus,10+step*5/19);shield.ColdBonus=Math.Max(shield.ColdBonus,10+step*5/19);shield.PoisonBonus=Math.Max(shield.PoisonBonus,10+step*5/19);shield.EnergyBonus=Math.Max(shield.EnergyBonus,10+step*5/19);shield.SkillBonuses.SetValues(0,SkillName.Parry,10+step*5/19);Equipment.Name=Kind==0?"Boarding shield":"Companion's shield";}else if(book!=null){book.Attributes.CastSpeed=Math.Max(book.Attributes.CastSpeed,2);book.Attributes.CastRecovery=Math.Max(book.Attributes.CastRecovery,6);book.Attributes.SpellDamage=Math.Max(book.Attributes.SpellDamage,20+step*30/19);book.Attributes.LowerManaCost=Math.Max(book.Attributes.LowerManaCost,10);book.Attributes.RegenMana=Math.Max(book.Attributes.RegenMana,3+step*3/19);book.Attributes.BonusMana=Math.Max(book.Attributes.BonusMana,20+step*30/19);Equipment.Name="Companion's grimoire";}var talisman=Equipment as HavenConcordTalisman;if(talisman!=null){talisman.Attributes.Luck=300+step*5;talisman.Attributes.BonusStr=talisman.Attributes.BonusDex=talisman.Attributes.BonusInt=10+Level/5;Equipment.Name="Haven talisman of concord";talisman.UnlockFollower(Equipment.Parent as Mobile);}var ring=Equipment as HavenSetRing;if(ring!=null){var baseline=HavenJewelrySets.CreateBracelet(ring.Theme);ring.Attributes.Luck=baseline.Attributes.Luck+step*5;ring.Attributes.BonusStr=baseline.Attributes.BonusStr+Level/5;ring.Attributes.BonusDex=baseline.Attributes.BonusDex+Level/5;ring.Attributes.BonusInt=baseline.Attributes.BonusInt+Level/5;baseline.Delete();Equipment.Name=HavenJewelrySets.Names[ring.Theme]+" ring";}Equipment.Name+=" [level "+Level+"/20]";Equipment.InvalidateProperties();}
  public override void OnDelete(){if(Equipment!=null){HavenEquipmentEvolution current;if(Records.TryGetValue(Equipment.Serial.Value,out current)&&current==this)Records.Remove(Equipment.Serial.Value);}base.OnDelete();}
  public static void Initialize(){Timer.DelayCall(TimeSpan.FromMinutes(1),TimeSpan.FromMinutes(1),()=>{foreach(var record in Records.Values.ToArray())if(record.Equipment==null||record.Equipment.Deleted)record.Delete();});CommandSystem.Register("gearprogress",AccessLevel.Player,e=>e.Mobile.Target=new ProgressTarget());EventSink.CreatureDeath+=e=>{var victim=e.Creature as BaseCreature;var owner=e.Killer==null?null:e.Killer.GetDamageMaster(victim)??e.Killer;if(!HavenStarterGear.Eligible(victim,owner))return;int xp=Math.Max(1,Math.Min(20,victim.HitsMax/100));foreach(var item in owner.Items){if(item is HavenSetRing||item is HavenConcordTalisman)Attach(item,4);var record=Find(item);if(record!=null&&(record.Kind==0||record.Kind==4))record.Gain(xp);}foreach(var companion in victim.DamageEntries.Select(x=>x.Damager).OfType<HavenCompanion>().Distinct()){if(companion.BoundOwner!=owner||companion.Map!=victim.Map||!companion.InRange(victim,18))continue;foreach(var item in companion.Items){var record=Find(item);if(record!=null)record.Gain(xp);}}};EventSink.ServerStarted+=()=>{if(!HavenPreview.Enabled)return;foreach(var c in World.Mobiles.Values.OfType<HavenCompanion>().ToArray())c.EnsureEvolvingEquipment();};}
  class ProgressTarget:Target{public ProgressTarget():base(12,false,TargetFlags.None){}protected override void OnTarget(Mobile p,object target){var item=target as Item;var c=item==null?null:item.RootParent as HavenCompanion;if(item==null||(item.RootParent!=p&&(c==null||!c.CanOpenPack(p))))return;var record=Find(item);p.SendMessage(record==null?"That item has no evolving progression.":item.Name+": "+record.Experience+" / 1900 XP. Earn XP while equipped on credited hostile kills.");}}
  public override void Serialize(GenericWriter w){base.Serialize(w);w.Write(0);w.Write(Equipment);w.Write(Experience);w.Write(Kind);}
  public override void Deserialize(GenericReader r){base.Deserialize(r);r.ReadInt();Equipment=r.ReadItem();Experience=r.ReadInt();Kind=r.ReadInt();if(Equipment!=null)Records[Equipment.Serial.Value]=this;Timer.DelayCall(TimeSpan.Zero,()=>{if(Equipment==null||Equipment.Deleted)Delete();else Apply();});}
 }
 public partial class HavenCompanion {
  public void EnsureEvolvingEquipment(){HavenEquipmentEvolution.Attach(_roleSword,1);HavenEquipmentEvolution.Attach(_roleBow,1);HavenEquipmentEvolution.Attach(_roleShield,3);if(_role==CompanionRole.Caster){EnsureSpellweaverSkills();var book=Items.OfType<Spellbook>().FirstOrDefault(x=>!x.Movable&&x.Name!=null&&x.Name.StartsWith("Companion's grimoire"))??(Backpack==null?null:Backpack.FindItemsByType(typeof(Spellbook),true).OfType<Spellbook>().FirstOrDefault(x=>!x.Movable&&x.Name!=null&&x.Name.StartsWith("Companion's grimoire")));if(book==null){book=new Spellbook(ulong.MaxValue){Movable=false};}HavenEquipmentEvolution.Attach(book,2);if(book.Parent!=this)AddItem(book);}}
 }
}
